:root {
  --ink: #263526;
  --leaf: #416a46;
  --pollen: #f4bc3e;
  --cream: #fff9e8;
  --line: #d8c98e;
}

.hive-card {
  width: 440px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--cream);
  color: var(--ink);
}

.hive-card header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
}

.seal {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 50%;
  background: var(--pollen);
  font-size: 22px;
}

.hive-card h1 {
  margin: 0 0 2px;
  font-size: 19px;
  line-height: 1.1;
}

.hive-card p {
  margin: 0;
  color: var(--leaf);
  font-size: 14px;
}

.hive-card footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  font-size: 13px;
}

.hive-card button {
  border: 0;
  border-radius: 999px;
  padding: 6px 11px;
  background: var(--leaf);
  color: var(--cream);
  font-weight: 700;
}
